<script setup>
import { useAuthStore } from '../stores/auth'
import { dateLabel, erp, money, useWorkspace } from '../composables/erp'
const auth = useAuthStore()
const { data, error, loading, refresh } = useWorkspace(id => erp(id, 'dashboard/'))
const stages = [['new', 'New'], ['qualified', 'Qualified'], ['proposition', 'Proposition'], ['won', 'Won'], ['lost', 'Lost']]
function pipeline(stage) { return data.value?.pipeline.find(item => item.stage === stage) || { count: 0, value: 0 } }
function width(stage) { return `${Math.max(3, Number(pipeline(stage).value) / Math.max(...data.value.pipeline.map(item => Number(item.value)), 1) * 100)}%` }
</script>
<template>
  <section class="business-page"><div class="control-panel"><div class="control-title"><h1>Overview</h1><span class="muted">{{ auth.activeCompany?.name || 'Your business' }}</span></div><button class="button-secondary" :disabled="loading" @click="refresh">Refresh</button></div><div class="workspace-content dashboard-content">
    <p v-if="!auth.activeCompanyId" class="empty-state">Create your first company to get started. <RouterLink to="/companies" class="text-link">Open companies →</RouterLink></p>
    <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="loading" class="loading-state" role="status">Loading your overview…</p>
    <template v-if="data">
      <div class="metrics-grid"><RouterLink to="/sales" class="metric-card"><span>Confirmed sales</span><strong>{{ money(data.sales_total, data.currency) }}</strong><small>{{ data.quotations }} open quotations</small></RouterLink><RouterLink to="/crm" class="metric-card purple"><span>Pipeline value</span><strong>{{ money(data.pipeline_value, data.currency) }}</strong><small>{{ data.open_opportunities }} open opportunities</small></RouterLink><RouterLink to="/invoicing" class="metric-card teal"><span>Customer receivables</span><strong>{{ money(data.receivable, data.currency) }}</strong><small>Issued invoices · remaining balance</small></RouterLink><RouterLink to="/invoicing" class="metric-card orange"><span>Vendor payables</span><strong>{{ money(data.payable, data.currency) }}</strong><small>Issued vendor bills · remaining balance</small></RouterLink></div>
      <div class="dashboard-columns"><section class="panel pipeline-chart"><div class="section-heading"><h2>Opportunity pipeline</h2><RouterLink to="/crm" class="text-link">Open CRM →</RouterLink></div><RouterLink v-for="[stage, label] in stages" :key="stage" :to="`/crm?stage=${stage}`" class="pipeline-row"><span>{{ label }} <small>{{ pipeline(stage).count }}</small></span><div class="bar-track"><div class="bar-fill" :class="stage" :style="{ width: width(stage) }"></div></div><strong>{{ money(pipeline(stage).value, data.currency) }}</strong></RouterLink></section><section class="panel operational-panel"><h2>Keep things moving</h2><RouterLink to="/contacts"><span>Active contacts</span><strong>{{ data.contacts }}</strong></RouterLink><RouterLink to="/inventory"><span>Active products</span><strong>{{ data.products }}</strong></RouterLink><RouterLink to="/inventory"><span>Products at low stock</span><strong class="warning-label">{{ data.low_stock }}</strong></RouterLink><RouterLink to="/tasks"><span>Open tasks</span><strong>{{ data.open_tasks }}</strong></RouterLink><RouterLink to="/tasks"><span>Overdue tasks</span><strong class="warning-label">{{ data.overdue_tasks }}</strong></RouterLink></section></div>
      <div class="dashboard-columns"><section class="panel"><div class="section-heading"><h2>Recent orders</h2><RouterLink to="/sales" class="text-link">View sales →</RouterLink></div><div class="table-wrap"><table v-if="data.recent_orders.length" class="data-table"><thead><tr><th>Reference</th><th>Partner</th><th>Total</th><th>Status</th></tr></thead><tbody><tr v-for="order in data.recent_orders" :key="order.id"><td><RouterLink :to="`${order.kind === 'sale' ? '/sales' : '/purchase'}/${order.id}`" class="text-link">{{ order.number }}</RouterLink></td><td>{{ order.contact_name }}</td><td>{{ money(order.total, order.currency) }}</td><td><span class="badge" :class="order.status">{{ order.status }}</span></td></tr></tbody></table><p v-else class="muted">Orders will appear here after you create your first quotation or RFQ.</p></div></section><section class="panel activity-panel"><h2>Recent activity</h2><p v-if="!data.activities.length" class="muted">Your team's business activity will appear here.</p><div v-for="activity in data.activities" :key="activity.id" class="activity-item"><span class="activity-dot"></span><div><span>{{ activity.summary }}</span><small>{{ activity.actor_email }} · {{ dateLabel(activity.created_at) }}</small></div></div></section></div>
    </template>
  </div></section>
</template>
